bool oom_reap_task(struct task_struct *tsk, struct mm_struct *mm)
{
    bool success = false;
    struct vm_area_struct *vma;

    mutex_lock(&mm->mmap_mutex);
    if (down_read_trylock(&mm->mmap_sem)) {
        if (atomic_read(&mm->mm_count)) {
            if (unlikely(mm->notifiers))
                schedule();

            if (!(mm->flags & MMF_OOM_SKIP)) {
                mm->flags |= MMF_OOM_SKIP;
                mm->context.oom_unstable = true;

                for (vma = mm->mmap; vma; vma = vma->vm_next) {
                    if ((vma->vm_flags & VM_ANON) && !(vma->vm_flags & VM_SHARED)) {
                        do_munmap(mm, vma->vm_start, vma->vm_end - vma->vm_start, 0);
                    }
                }

                pr_info("OOM reaped process %d (%s) with %lu pages unmapped.\n",
                        tsk->pid, tsk->comm, get_mm_rss(mm));
                success = true;
            }

            up_read(&mm->mmap_sem);
        }
    } else {
        pr_debug("OOM reaping failed to acquire mmap_sem for task %d\n", tsk->pid);
    }

    mutex_unlock(&mm->mmap_mutex);
    return success;
}

bool oom_reap_task(struct task_struct *tsk, struct mm_struct *mm)
{
    bool success = false;
    struct vm_area_struct *vma, *vma_next;

    mutex_lock(&mm->oom_reap_lock);

    if (!down_read_trylock(&mm->mmap_lock)) {
        pr_debug("Failed to acquire mmap_lock\n");
        goto out_unlock;
    }

    if (atomic_read(&mm->mm_count) < 1) {
        pr_debug("Memory management structure already freed\n");
        goto out_unlock_mm;
    }

    if (mm->oom_notifier.notifier_call) {
        schedule_timeout_uninterruptible(HZ / 10);
    }

    if (mm->flags & MMF_OOM_SKIP) {
        pr_debug("Skipping OOM reaping for process %d\n", tsk->pid);
        goto out_unlock_mm;
    }

    mm->flags |= MMF_OOM_REAPING;

    do {
        vma = find_vma_intersection(mm, 0, -1);
        while (vma) {
            vma_next = vma->vm_next;

            if ((vma->vm_flags & (VM_ANON | VM_SHARED)) == VM_ANON) {
                do_munmap(mm, vma->vm_start, vma->vm_end - vma->vm_start, 0);
            }

            vma = vma_next;
        }
    } while (0);

    pr_info("Reaped process %d (oom skip flag set: %d)\n", tsk->pid,
            mm->flags & MMF_OOM_SKIP);

    success = true;

out_unlock_mm:
    up_read(&mm->mmap_lock);
out_unlock:
    mutex_unlock(&mm->oom_reap_lock);
    return success;
}

bool oom_reap_task(struct task_struct *tsk, struct mm_struct *mm)
{
    bool success = false;
    int ret;

    mutex_lock(&mm->oom_lock);

    ret = down_read_trylock(&mm->mmap_lock);
    if (!ret) {
        pr_info("Failed to acquire mmap_lock for task %d\n", tsk->pid);
        goto out_unlock_oom;
    }

    if (atomic_read(&mm->oom_notifiers)) {
        schedule_timeout_uninterruptible(HZ / 10);
    }

    if (test_bit(MMF_OOM_SKIP, &mm->flags)) {
        pr_info("Reaping skipped for task %d due to MMF_OOM_SKIP flag\n", tsk->pid);
        goto out_unlock;
    }

    set_bit(MMF_OOM_REAPING, &mm->flags);

    for (struct vm_area_struct *vma = mm->mmap; vma; vma = vma->vm_next) {
        if (vma->vm_flags & (VM_ANON | VM_SHARED)) {
            do_munmap(mm, vma->vm_start, vma->vm_end - vma->vm_start, 0);
        }
    }

    pr_info("Successfully reaped task %d (PID: %d) with %lu pages unmapped\n", tsk, tsk->pid, atomic_read(&mm->total_vm));

    success = true;

out_unlock:
    up_read(&mm->mmap_lock);
out_unlock_oom:
    mutex_unlock(&mm->oom_lock);

    return success;
}

bool oom_reap_task(struct task_struct *tsk, struct mm_struct *mm) {
    bool ret = false;

    mutex_lock(&mm->oom_lock);
    if (!down_read_trylock(&mm->mmap_lock)) {
        pr_info("Failed to acquire mmap_lock for task %d\n", tsk->pid);
        goto out_unlock_oom;
    }

    if (atomic_read(&mm->mm_count)) {
        schedule();
    }

    if (mm->flags & MMF_OOM_SKIP) {
        pr_info("OOM reaping skipped for task %d\n", tsk->pid);
        goto out_unlock_mmap;
    }

    mm->flags |= MMF_OOM_REAP;

    for (struct vm_area_struct *vma = mm->mmap; vma; vma = vma->vm_next) {
        if ((vma->vm_flags & (VM_ANON | VM_SHARED)) == VM_ANON) {
            do_munmap(mm, vma->vm_start, vma->vm_end - vma->vm_start, 0);
        }
    }

    pr_info("OOM reaping successful for task %d\n", tsk->pid);
    ret = true;

out_unlock_mmap:
    up_read(&mm->mmap_lock);
out_unlock_oom:
    mutex_unlock(&mm->oom_lock);

    return ret;
}

bool reap_task_memory(struct task_struct *tsk, struct mm_struct *mm)
{
    bool success = false;
    struct vm_area_struct *vma, *tmp;

    mutex_lock(&mm->oom_lock);

    if (!down_read_trylock(&mm->mmap_sem)) {
        pr_info("Failed to acquire mmap semaphore\n");
        goto out_unlock_oom;
    }

    if (atomic_read(&mm->mm_count) > 1)
        schedule_timeout_uninterruptible(HZ / 10);

    if (mm->flags & MMF_OOM_SKIP)
        goto out_unlock;

    mm->flags |= MMF_OOM_REAPING;

    do {
        int ret;

        for (vma = mm->mmap; vma; vma = vma->vm_next) {
            if ((vma->vm_flags & (VM_ANON | VM_SHARED)) == VM_ANON) {
                ret = do_munmap(mm, vma->vm_start, vma->vm_end - vma->vm_start, 0);
                if (ret)
                    pr_info("Failed to unmap anonymous VMA at %lx-%lx\n", vma->vm_start, vma->vm_end);
            }
        }

        success = true;

    } while (0);

    pr_info("Reaped memory from task %d (OOM)\n", tsk->pid);

out_unlock:
    up_read(&mm->mmap_sem);
out_unlock_oom:
    mutex_unlock(&mm->oom_lock);

    return success;
}
